package com.fitbite.exception;
import com.fitbite.dto.ApiResponse; import org.springframework.http.*; import org.springframework.web.bind.MethodArgumentNotValidException; import org.springframework.web.bind.annotation.*; import java.util.stream.Collectors;
@RestControllerAdvice public class GlobalExceptionHandler { @ExceptionHandler(ResourceNotFoundException.class) ResponseEntity<ApiResponse<Void>> notFound(ResourceNotFoundException e){return ResponseEntity.status(404).body(ApiResponse.error(e.getMessage(),"NOT_FOUND"));} @ExceptionHandler(IllegalArgumentException.class) ResponseEntity<ApiResponse<Void>> bad(IllegalArgumentException e){return ResponseEntity.badRequest().body(ApiResponse.error(e.getMessage(),"BAD_REQUEST"));} @ExceptionHandler(MethodArgumentNotValidException.class) ResponseEntity<ApiResponse<Void>> validation(MethodArgumentNotValidException e){String m=e.getBindingResult().getFieldErrors().stream().map(x->x.getField()+": "+x.getDefaultMessage()).collect(Collectors.joining("; "));return ResponseEntity.badRequest().body(ApiResponse.error(m,"VALIDATION_ERROR"));} @ExceptionHandler(Exception.class) ResponseEntity<ApiResponse<Void>> generic(Exception e){return ResponseEntity.status(500).body(ApiResponse.error("An unexpected error occurred.","INTERNAL_ERROR"));} }
